for i in range(1, N + 1):
dp[i][1][0] = dp[i][1][1] = 1

for k in range(2, K + 1):
# forward dir
for n in range(N, 0, -1):
ans = 2

if n < N:
ans += dp[n + 1][k][0] - 1
ans %= mod

if n > 1:
ans += dp[n - 1][k - 1][1] - 1
ans %= mod

dp[n][k][0] = ans

# backward dir
for n in range(1, N + 1):
ans = 2

if n < N:
ans += dp[n + 1][k - 1][0] - 1
ans %= mod

if n > 1:
ans += dp[n - 1][k][1] - 1
ans %= mod

dp[n][k][1] = ans

return dp[1][K][0]

t = int(input())

