s2.clear();
for (int i: s) s2.insert(i >> 1);
swap(s, s2); 
}

int ans;
if (l % 2 == 0) ans = r;
else ans = l;

for (int i: s) {
if (s.find(i ^ 1) == s.end()) {
int cur = i ^ ans;
bool f = true;
for (int j : s)
f &= ((cur ^ j) >= l && (cur ^ j) <= r);
if (f) {
ans = cur;
break;
}
}
}
cout << ans * mul << '\n';
}

