const uint NO = 1<<30;
template<unsigned K>
struct VebTree{
uint mn, mx;
VebTree<(K>>1)> *m[1<<((K+1)>>1)];
VebTree<((K+1)>>1)> *aux;

VebTree(){
memset(m, 0, sizeof(m));
aux = 0;
mn = mx = NO;
}

inline bool empty() const{
return mx==NO;
}

inline uint high(uint x) const{
return x>>(K>>1);
}

inline uint low(uint x) const{
return x&((1<<(K>>1))-1);
}

inline uint merge(uint x, uint y) const{
return (x<<(K>>1))+y;
}

bool find(uint x){
if(x==mn || x==mx) return 1;
return m[high(x)] && m[high(x)]->find(low(x));
}

void insert(uint x){
if(mx==NO) mn = mx = x;
else if(mn==mx) mn = min(mn, x), mx = max(mx, x);
else if(x<mn || x>mx){
uint add = x<mn ? mn : mx;
mn = min(mn, x);
mx = max(mx, x);
insert(add);
}
else if(K>1){
uint hi = high(x), lo = low(x);
if(!m[hi]) m[hi] = new VebTree<(K>>1)>();
if(m[hi]->empty()){
if(!aux) aux = new VebTree<((K+1)>>1)>();
aux->insert(hi);
}
m[hi]->insert(lo);
}
}

void rem(uint x){
if(mn==mx){
mn = mx = NO;
return;
}
if(x==mn){
if(!aux || aux->empty()) {mn=mx; return;}
else mn = x = merge(aux->mn, m[aux->mn]->mn);
}
else if(x==mx){
if(!aux || aux->empty()) {mx = mn; return;}
else mx = x = merge(aux->mx, m[aux->mx]->mx);
}
uint hi = high(x), lo = low(x);
m[hi]->rem(lo);
if(m[hi]->empty()) aux->rem(hi);
}

uint next(uint x){
if(empty() || x>=mx) return NO;
if(x<mn) return mn;
if(K==1) return mx;
uint hi = high(x), lo = low(x);
if(m[hi] && !m[hi]->empty() && m[hi]->mx > lo) return merge(hi, m[hi]->next(lo));
uint next_hi = aux ? aux->next(hi) : NO;
return next_hi==NO ? mx : merge(next_hi, m[next_hi]->mn);
}

uint prev(uint x){
if(empty() || x<=mn) return NO;
if(x>mx) return mx;
if(K==1) return mn;
uint hi = high(x), lo = low(x);
if(m[hi] && !m[hi]->empty() && m[hi]->mn < lo) return merge(hi, m[hi]->prev(lo));
uint prev_hi = aux ? aux->prev(hi) : NO;
return prev_hi==NO ? mn : merge(prev_hi, m[prev_hi]->mx);
}
};

const int G = 1e5 + 5, SZB = 300;
int a, z;
int m[G], ans[G];
int cng[G], cnt[G];
array<int, 3> que[G];
int cl, cr;
VebTree<32> veb, lox;

void add(int ps) {
int res = ++cnt[cng[ps]];
if(res==1){
veb.insert(m[ps]);
}
if(res==2){
lox.insert(m[ps]);
}
}

void rem(int ps) {
int res = --cnt[cng[ps]];
if(res==0){
veb.rem(m[ps]);
}
if(res==1){
lox.rem(m[ps]);
}
}

uint go() {
uint o = 0;
uint mn = NO;
vec<int> del;
for(int k=29; k>=0; k--){
uint x = o+(1<<k);
uint cur = veb.prev(x), sz = 0;
if(cur!=NO && cur>=o){
++sz;
cur = veb.prev(cur);
if(cur!=NO && cur>=o){
++sz;
}
}
if(sz==0) o += 1<<k;
else if(sz==1){
uint c = veb.prev(x)+(1<<k);
if(veb.find(c)) chmin(mn, c);
else {
veb.insert(c);
del.pb(c);
}
o += 1<<k;
}
}
for(uint i : del) veb.rem(i);
return min({mn, o, lox.mn});
}

