cin >> a >> b;
a--;
ts[b - 1].emplace_back(a, i);
qlen.emplace_back(b - a);
}

int a = 0;
for (int i = 0; i < t[0].size(); i++) {
// cout << i << ' ' << t[0][i] << '\n';
for (auto j : ts[i]) {
h.emplace(j);
}

a = g[a].nx[t[0][i] - 'a'];

if (g[a].pp != -1) { // bug ignore
int id = g[g[a].pp].id;
int bg = i + 1 - (int)s[0][id].size();
while (h.size() > 0 && h.top().x >= bg) {
