pos+=2;
}
pos++;
}
return ans;
}
void solve(){ 
ll n,ans=0; cin>>n;
string s; cin>>s; 
for(ll i=0;i<n;i++){
string t; 
for(ll j=i;j<n;j++){
t.push_back(s[j]);
ans+=f(t);
}
}
cout<<ans<<nline;
return; 
} 
