ntp[i * prime[j]] = 1;

if (!(i % prime[j]))
break;
}
}
}
int gcd(int x, int y) {
return x ? gcd(y % x, x) : y;
}
bool no(int l, int r, int k) {
while (k > 1) {
int x = mn[k];

while (k % x == 0)
k /= x;

if (((l + x - 1) / x) * x <= r)
return 0;
}

return 1;
}

int main() {
sieve(20000000);
int i, j = 0, T, n, m, a, b, u, v, g = 0, S = 0, px, py, qwq = 0;
ll ans;
prime[0] = 1;

for (i = 2; i <= 20000000; i++) {
while (j < cnt && prime[j + 1] <= i)
j++;

pos[i] = j;
}

scanf("%d", &T);

