if (n < m) {
swap(n, m);
swap(a, b);
}

u = prime[pos[n]];
v = m;

while (v && !no(u, n, v))
v--;

ans = 0;
px = py = 0;

for (i = u; i <= n; i++)
for (j = v; j <= m && j <= i; j++) {
bad[i - u + 1][j - v + 1] = ((bad[i - u][j - v + 1] && bad[i - u + 1][j - v]) || gcd(i, j) > 1);

if (!bad[i - u + 1][j - v + 1]) {
ans = max(ans, (ll)a * i + (ll)b * j);

