2009G2.editorial_text:
2009G2 - Yunli's Subarray Queries (hard version)
Analysis: Solution 1: Proof_by_QED, Solution 2: awesomeguy856

Prologue
First, read the solution to the easy version of the problem to compute the answer for every window of $$$k$$$. Let $$$c_i=f([a_i, ..., a_{i+k-1}])$$$. Now, the problem simplifies to finding 
$$$\sum_{j=l}^{r-k+1} ( \min_{i=l}^{j} c_i)$$$

Solution 1 (Lazy Segment Tree, Offline)
We will answer the queries offline in decreasing order of $$$l$$$. We maintain a lazy segment tree. We have a variable $$$x$$$ sweeping from $$$n-k$$$ to $$$0$$$. As the variable sweeps leftwards, in node $$$i$$$ of the segment tree, we keep track of $$$\min_{j=x}^{i}c_i$$$. 
To decrease the value of $$$x$$$, we note that the range $$$[x-1, y]$$$ in the segment tree will be set to $$$c_{x-1}$$$, where $$$y$$$ is the largest value such that $$$c_y \gt c_{x-1}$$$ but $$$c_{y+1}\leq c_{x-1}$$$ (or $$$y=n-1$$$). To find the $$$y$$$ for each $$$x$$$, we may either walk/binary search in the segment tree, or use a monotonic stack. 

Code (C++) (vgoofficial)
#include "bits/stdc++.h"
#define int long long

template <typename T>
std::ostream& operator<<(std::ostream& os, const std::vector<T>& vec) {
os << "[ ";
for (const auto& elem : vec) {
os << elem << " ";
}
os << "]";
return os;
}

using namespace std;

int getAns(int& k, multiset<int>& ms) { return k - (*ms.rbegin()); }
struct SegTree {
int n;
vector<int> tree, setLazy, begin, end;
void prop(int i) {
if (setLazy[i] != -100) {
setLazy[2 * i + 1] = setLazy[2 * i] = setLazy[i];
tree[2 * i] = tree[2 * i + 1] =
setLazy[i] * (end[2 * i + 1] - begin[2 * i + 1] + 1);
setLazy[i] = -100;
}
}
SegTree(int nn) {
n = 1;
while (n < nn) n *= 2;
tree.resize(2 * n);
setLazy.resize(2 * n, -100);
begin.resize(2 * n);
end.resize(2 * n);
for (int i = n; i < 2 * n; i++) {
begin[i] = end[i] = i - n;
}
for (int i = n - 1; i > 0; i--) {
begin[i] = begin[2 * i];
end[i] = end[2 * i + 1];
}
}
void rangeSet(int i, int amt, int lo, int hi) {
if (i < n) prop(i);
if (begin[i] == lo && end[i] == hi) {
tree[i] = amt * (hi - lo + 1);
setLazy[i] = amt;
return;
}
if (begin[2 * i] <= hi && end[2 * i] >= lo) {
rangeSet(2 * i, amt, lo, min(hi, end[2 * i]));
}
if (begin[2 * i + 1] <= hi && end[2 * i + 1] >= lo) {
rangeSet(2 * i + 1, amt, max(lo, begin[2 * i + 1]), hi);
}
tree[i] = tree[2 * i] + tree[2 * i + 1];
}
int query(int i, int lo, int hi) {
if (i < n) prop(i);
if (begin[i] == lo && end[i] == hi) return tree[i];
int ans = 0;
if (begin[2 * i] <= hi && end[2 * i] >= lo) {
ans += query(2 * i, lo, min(end[2 * i], hi));
}
if (begin[2 * i + 1] <= hi && end[2 * i + 1] >= lo) {
ans += query(2 * i + 1, max(lo, begin[2 * i + 1]), hi);
}
return ans;
}
};
signed main() {
int t;
cin >> t;
while (t--) {
int n, k, q;
cin >> n >> k >> q;
vector<int> v(n);
for (int i = 0; i < n; i++) {
cin >> v[i];
v[i] = v[i] - i;
}
vector<int> ans(n); // ans[i] is answer from i to i+k-1
map<int, int> mp;
multiset<int> active;
for (int i = 0; i < k; i++) {
if (mp[v[i]] == 0) {
mp[v[i]] = 1;
active.insert(1);
} else {
active.erase(active.find(mp[v[i]]));
mp[v[i]]++;
active.insert(mp[v[i]]);
}
}
ans[0] = getAns(k, active);
for (int i = k; i < n; i++) {
// erase v[i-k]
active.erase(active.find(mp[v[i - k]]));
mp[v[i - k]]--;
if (mp[v[i - k]] != 0) active.insert(mp[v[i - k]]);

if (mp[v[i]] == 0) {
mp[v[i]] = 1;
active.insert(1);
} else {
active.erase(active.find(mp[v[i]]));
mp[v[i]]++;
active.insert(mp[v[i]]);
}
ans[i - k + 1] = getAns(k, active);
}
vector<array<int, 3>> queries(q);
vector<int> an(q);
for (int i = 0; i < q; i++) {
queries[i][2] = i;
cin >> queries[i][0] >> queries[i][1];
queries[i][0]--;
queries[i][1]--;
queries[i][0] *= -1;
}
sort(begin(queries), end(queries));
for (int i = 0; i < q; i++) queries[i][0] *= -1;
SegTree st(n);
st.rangeSet(1, ans[n - k], n - k, n - k);
int cur = n - k;
stack<pair<int, int>> s;
s.push({ans[n - k], n - k});
for (int i = 0; i < q; i++) {
while (cur != queries[i][0]) {
cur--;
int here = cur;
while (s.size() && s.top().first > ans[cur]) {
here = s.top().second;
s.pop();
}
s.push({ans[cur], here});
st.rangeSet(1, ans[cur], cur, here);
}
an[queries[i][2]] =
st.query(1, queries[i][0], queries[i][1] - k + 1);
}
for (auto x : an) cout << x << endl;
}
}

Solution 2 (Binary Lifting, Online)
Let $$$p_i$$$ be the smallest value $$$j \gt i$$$ such that $$$c_j \lt c_i.$$$ We can calculate these values using a monotonic stack and iterating through $$$c$$$ backwards. If such $$$j$$$ does not exist, then we let $$$p_i=n.$$$ Then $$$f(h,i)=c_i$$$ for all $$$i\le h-k+1 \lt p_i.$$$ Further, $$$f(h,i)=c_{p_i}$$$ for $$$p_i\le h-k+1 \lt p_{p_i},$$$ and so on. 
Now, let $$$w(0,i)=i,$$$ and $$$w(h,i)=p_{w(h-1,i)}$$$ for $$$h \gt 0.$$$ To calculate the answer for a query $$$(l,r),$$$ consider the largest value of $$$j$$$ such that $$$w(j,l)\le r.$$$ Then we can take the sum $$$c_{w(j,l)}\cdot(r-w(j,l)+1)+\sum_{i=1}^jc_{w(i-1,l)}\cdot(w(i,l)-w(i-1,l)).$$$ 
Now it remains to quickly calculate this sum. We can use binary lifting to solve this. Specifically, we create an $$$n\times20$$$ data table where $$$d[i][j]=\sum_{h=1}^{2^j}c_{w(h-1,i)}\cdot(w(h,i)-w(h-1,i)),$$$ if $$$w(2^j,i)$$$ exists, and $$$-1$$$ otherwise. We can precompute this table recursively, as $$$d[i][0]=c_i\cdot(w(1,i)-i)$$$ and $$$d[i][j]=d[i][j-1]+d[w(2^{j-1},i)][j-1].$$$ 
Then, to answer queries, we iterate $$$j$$$ from $$$19$$$ to $$$0,$$$ and if $$$w(2^j,l)\le r,$$$ we add $$$d[l][j]$$$ to our answer, and set $$$l=w(2^j,l).$$$ At the end, we add $$$c_l\cdot(r-l+1)$$$ to our answer.

Code (C++) (awesomeguy856)
#include <bits/stdc++.h>
#define int long long
#define pii pair<int, int>
#define fi first
#define se second
using namespace std;
void solve() {
int n, k, q;
cin >> n >> k >> q;
vector<int> a(n);
for (int &r : a) cin >> r;
vector<int> c(3 * n), v(n);
multiset<int> s;
for (int i = 0; i < k; i++) c[a[i] - i + n - 1]++;
for (int r : c) s.insert(r);
v[k - 1] = k - *s.rbegin();
for (int i = k; i < n; i++) {
int x = a[i] - i + n - 1, y = a[i - k] - i + k + n - 1;
c[x]++;
s.erase(s.find(c[x] - 1));
s.insert(c[x]);
c[y]--;
s.erase(s.find(c[y] + 1));
s.insert(c[y]);
v[i] = k - *s.rbegin();
}
vector<int> l(n, -1);
stack<pii> t;
for (int i = k - 1; i < n; i++) {
while (!t.empty()) {
if (t.top().se <= v[i]) break;
l[t.top().fi] = i;
t.pop();
}
t.push({i, v[i]});
}
vector<vector<pii>> w(n, vector<pii>(20, {-1, -1}));
for (int i = n - 1; i >= k - 1; i--) {
w[i][0].se = l[i];
if (l[i] < 0) {
w[i][0].fi = (n - i) * v[i];
continue;
}
w[i][0].fi = (l[i] - i) * v[i];
for (int j = 1; j < 20; j++) {
if (w[w[i][j - 1].se][j - 1].se < 0) break;
w[i][j].se = w[w[i][j - 1].se][j - 1].se;
w[i][j].fi = w[i][j - 1].fi + w[w[i][j - 1].se][j - 1].fi;
}
}
while (q--) {
int l, r, ans = 0;
cin >> l >> r;
l--;
r--;
l += k - 1;
for (int j = 19; ~j; j--) {
if (w[l][j].se < 0) continue;
if (w[l][j].se > r) continue;
ans += w[l][j].fi;
l = w[l][j].se;
}
cout << ans + v[l] * (r - l + 1) << "\n";
}
}
int32_t main() {
ios::sync_with_stdio(0);
cin.tie(0);
int t;
cin >> t;
while (t--) solve();
}

2009G3.editorial_text:
2009G3 - Yunli's Subarray Queries (extreme version)
Analysis: Dominater069

Solution 
I decided to write the Editorial for this problem in a step-by-step manner. Some of the steps are really short and meant to be used as hints but i decided to have a uniform naming for everything.

Step 1
Continuing from the easier versions of the problem, we know we need to compute sum of min of subarrays, and answer subarray queries on this. Consider the standard approach of finding sum of min over all subarrays.

Step 2
Sum of min of all subarrays for a fixed array is a well known problem. Here is how you can solve it, given an array $$$a$$$ of length $$$n$$$.
Let $$$nx_i$$$ denote the smallest integer $$$j (j \gt i)$$$ such that $$$a_j \lt a_i$$$ holds, or $$$n + 1$$$ if no such integer exists. Similarly, define $$$pv_i$$$ denote the largest integer $$$j (j \lt i)$$$ such that $$$a_j \le a_i$$$ holds, or $$$0$$$ if no such integer exists.
The answer is simply $$$\sum_{i = 1}^{n} a_i \cdot (nx_i - i) \cdot (i - pv_i)$$$. Calculating $$$nx_i$$$ and $$$pv_i$$$ can be done with Monotonic Stack.

Step 3
Given a query $$$(L, R)$$$, divide all indices $$$i$$$ ($$$L \le i \le R$$$) into $$$4$$$ groups depending on the existence of $$$nx_i$$$ and $$$pv_i$$$ within the interval $$$[L, R]$$$, i.e. : 

Case $$$1$$$ : $$$L \le pv_i, nx_i \le R$$$

Case $$$2$$$ : $$$pv_i \lt L, nx_i \le R$$$

Case $$$3$$$ : $$$L \le pv_i, nx_i \gt R$$$

Case $$$4$$$ : $$$pv_i \lt L, nx_i \gt R$$$

Try to calculate the contributions of each of these categories separately.

Step 4
Case $$$1$$$ can be reduced to rectangle queries. Case $$$4$$$ is simple to handle as there is atmost $$$1$$$ element which satisfies that condition, which (if exists) is the minimum element in the range $$$(L, R)$$$ which can be found using any RMQ data structure like Sparse Table or Segment Tree.

What is Rectangle Queries?
Given a list of $$$n$$$ tuples $$$(l, r, v)$$$ and $$$q$$$ queries $$$(L, R)$$$ you have to add $$$v$$$ to answer of the $$$i$$$-th query if $$$L \lt = l \lt = r \lt = R$$$. 
This can be solved in $$$O((n + q) log(n))$$$ using Fenwick Tree and Sweepline. 
Iterate from $$$i = n$$$ to $$$i = 1$$$. For every tuple with left end at $$$i$$$ say $$$(i, j, v)$$$, add $$$v$$$ to a range query sum data structure at position $$$j$$$. Then, for every query with left end at $$$i$$$, we can simply query the range sum from $$$i = l$$$ to $$$i = r$$$ to get the required answer.

How to reduce Case 1 to Rectangle Queries?
For every index $$$i$$$ from $$$1$$$ to $$$n$$$, generate a tuple as $$$(pv_i, nx_i, a_i \cdot (i - pv_i) \cdot (nx_i - i)$$$. Then, solve the Rectangle Queries problem with this list of tuples. The answer will be the required contribution of all indices belonging to Case $$$1$$$.

Step 5
This leaves us with Case $$$2$$$ and $$$3$$$, which are symmetric, so we discuss only case $$$2$$$.
Let us sweepline from $$$i = n$$$ to $$$i = 1$$$, maintaining a Monotonic Stack of elements, popping elements when we find a smaller element, similar to how we find $$$pv_i$$$. 
The indices belonging to Case $$$2$$$ are precisely the elements present in the Monotonic Stack (obviously ignore any element $$$ \gt R$$$) when we have swept till $$$i = L$$$, with the possible exception of the minimum in the range $$$[L, R]$$$ (that might belong to Case $$$4$$$).

Step 6
Let's analyze the contribution of the indices in Case $$$2$$$. 
It is $$$a_i \cdot (L - i + 1) \cdot (nx_i - i)$$$.
Take a look at what happens when we go from $$$L$$$ to $$$L - 1$$$, how do all the contributions of elements belonging to Case $$$2$$$ change.

Step 7
Some elements get popped from the Monotonic Stack because $$$a_{L - 1}$$$. We need to reset the contribution of all these elements to $$$0$$$.
The elements that do not get popped have their contribution increased by exactly $$$(nx_i - i)$$$.
$$$1$$$ element gets added to the Monotonic Stack, which is $$$a_{L - 1}$$$, so we need to initiliatize its contribution to $$$(nx_{L - 1} - (L - 1)).$$$

Step 8
Resetting and Initiliazing Contribution is simple enough with most data structures, so let us focus on adding $$$(nx_i - i)$$$ to the elements present in the Monotonic Stack.
We can keep a Lazy Segment Tree with $$$2$$$ parameters, $$$sumcon=$$$ sum of all contributions in this segment tree node, and $$$addcon = $$$ sum of $$$(nx_i - i)$$$ of all "non-popped" elements in this node. The lazy tag will denote how many contribution increases I have to do. We can simply do $$$sumcon += lazy * addcon$$$ for the lazy updates.
Then, we can query the range sum from $$$L$$$ to $$$R$$$ to get the sum of contributions of all elements belonging to Case $$$2$$$. Case $$$3$$$ can be solved in a symmetric way. Adding up the answers over Case $$$1$$$, $$$2$$$, $$$3$$$ and $$$4$$$ will give us the required answer.

Minor Detail
We need to be quite careful with the Case $$$4$$$ element, as we might double count its contribution in Case $$$2$$$ and $$$3$$$. I handle this in the model solution by querying the sum of contribution in $$$[L, X - 1]$$$ where $$$X$$$ is the largest element present in the monostack which is $$$\le R$$$, and handling $$$X$$$ separately. You can easily note that $$$X$$$ is the only element belonging to Case $$$4$$$ (if any at all).

Code (C++) (awesomeguy856)
#include <bits/stdc++.h>
#define int long long
#define ll long long 
#define pii pair<int,int> 
#define piii pair<pii,pii>
#define fi first
#define se second
#pragma GCC optimize("O3,unroll-loops")
#pragma GCC target("avx2,bmi,bmi2,lzcnt,popcnt")
using namespace std;
struct segtree {
const static int INF = 1e18, INF2 = 0;
int l, r;
segtree* lc, * rc;
int v = INF, v2=0, v3=0, v4=0;
segtree* getmem();
segtree() : segtree(-1, -1) {};
segtree(int l, int r) : l(l), r(r) {
if (l == r) return;
int m = (l + r) / 2;
lc = getmem(); *lc = segtree(l, m);
rc = getmem(); *rc = segtree(m + 1, r);
}
int op(int a, int b) {
return min(a,b); 
}
int op2(int a, int b) {
return a+b; 
}
void add(int qi, int qv, int h, int h4=0) {
if (r < qi || l > qi) return;
if (l == r) { if (v==INF) v=qv; v2+=qv, v3+=qv*h; v4+=qv*h4; return;}
lc->add(qi, qv, h, h4); rc->add(qi, qv, h, h4);
v = op(lc->v, rc->v);
v2 = op2(lc->v2, rc->v2); 
v3 = op2(lc->v3, rc->v3); 
v4 = op2(lc->v4, rc->v4); 
}
int qrr(int ql, int qx) {
if (v>=qx||r<ql) return 1e9; 
if (l==r) return l; 
int k=lc->qrr(ql,qx); 
if (k<1e9) return k; 
return rc->qrr(ql,qx); 
}
int q2(int ql, int qr) {
if (l > qr || r < ql) return INF2;
if (ql <= l && r <= qr) return v2;
return op2(lc->q2(ql, qr), rc->q2(ql, qr));
}
int q3(int ql, int qr) {
if (l > qr || r < ql) return INF2;
if (ql <= l && r <= qr) return v3;
return op2(lc->q3(ql, qr), rc->q3(ql, qr));
}
int q4(int ql, int qr) {
if (l > qr || r < ql) return INF2; 
if (ql <= l && r <= qr) return v4; 
return op2(lc->q4(ql, qr), rc->q4(ql, qr)); 
}
};
segtree mem[2000005];int memsz = 0;
segtree* segtree::getmem() { return &mem[memsz++]; }
void solve() {
int n, k, q;
cin >> n >> k >> q;
vector<int> a(n);
for (int &r : a) cin >> r;
vector<int> c(2 * n), v(n);
multiset<int> s;
for (int i = 0; i < k; i++) c[a[i] - i + n - 1]++;
for (int r : c) s.insert(r);
v[k - 1] = k - *s.rbegin();
for (int i = k; i < n; i++) {
int x = a[i] - i + n - 1, y = a[i - k] - i + k + n - 1;
c[x]++;
s.erase(s.find(c[x] - 1));
s.insert(c[x]);
c[y]--;
s.erase(s.find(c[y] + 1));
s.insert(c[y]);
v[i] = k - *s.rbegin();
}
vector<int> ans(q);
vector<vector<pii>> w(n); 
segtree co(0, n+2), lb(0, n+2), e(0,n+2),e2(0,n+2); 
vector<int> rb(n); 
stack<int> t; 
for (int i = 0; i < q; i++) {
int l,r; cin >> l >> r; 
w[l+k-2].push_back({i,r-1}); 
}
for (int i = n-1; ~i; i--) {
e.add(i,v[i],i,i*i); 
int j=min(n,e.qrr(i,v[i])); 
rb[i]=j; 
e.add(j-1,-v[i],i,i*i);
e2.add(j,v[i]*(j-i),i);
while (!t.empty()) {
int x=t.top(); 
if (v[x]<v[i]) break;
t.pop(); 
co.add(rb[x],v[x]*(rb[x]-x)*(x-i),0); 
lb.add(x,v[x]*(x-i),x);
lb.add(rb[x]-1,-v[x]*(x-i),x); 
e.add(x,-v[x],x,x*x);
e.add(rb[x]-1,v[x],x,x*x);
e2.add(rb[x],-v[x]*(rb[x]-x),x); 
}
t.push(i); 
int l=i;
for (auto [p,r]:w[i]) {
int x=e.q2(l,r), y=e.q3(l,r), z=e.q4(l,r);
int f=y*(r+1)-z, g=x*(r+1)-y; 
int lx=lb.q2(l,r), ly=lb.q3(l,r); 
ans[p]=co.q2(l,r+1)+lx*(r+1)-ly+e2.q3(l,r+1)-e2.q2(l,r+1)*(i-1)+f-g*(i-1);
}
}
for (int r:ans) cout << r << "\n";
}

int32_t main() {
ios::sync_with_stdio(0); cin.tie(0);
int t = 1; cin >> t;
while (t--) solve();
}

2020A.editorial_text:
A. Find Min Operations
By nishkarsh

Hint 1
How many operations will have $$$x = 0$$$.

Hint 2
Try $$$k = 2$$$.

Solution for k = 2
Answer will be the number of ones in binary representation of $$$n$$$.

Solution
If $$$k$$$ is 1, we can only subtract 1 in each operation, and our answer will be $$$n$$$.
Now, first, it can be seen that we have to apply at least $$$n$$$ mod $$$k$$$ operations of subtracting $$$k^0$$$ (as all the other operations will not change the value of $$$n$$$ mod $$$k$$$). Now, once $$$n$$$ is divisible by $$$k$$$, solving the problem for $$$n$$$ is equivalent to solving the problem for $$$\frac{n}{k}$$$ as subtracting $$$k^0$$$ will be useless because if we apply the $$$k^0$$$ subtraction operation, then $$$n$$$ mod $$$k$$$ becomes $$$k-1$$$, and we have to apply $$$k-1$$$ more operations to make $$$n$$$ divisible by $$$k$$$ (as the final result, i.e., 0 is divisible by $$$k$$$). Instead of doing these $$$k$$$ operations of subtracting $$$k^0$$$, a single operation subtracting $$$k^1$$$ will do the job.
So, our final answer becomes the sum of the digits of $$$n$$$ in base $$$k$$$.
The complexity of the solution is $$$O(\log_{k}{n})$$$ per testcase.

Code
#include <bits/stdc++.h>
using namespace std;

int find_min_oper(int n, int k){
if(k == 1) return n;
int ans = 0;
while(n){
ans += n%k;
n /= k;
}
return ans;
}

int main()
{
int t;
cin >> t;
while(t--){
int n,k;
cin >> n >> k;
cout << find_min_oper(n,k) << "\n";
}
return 0;
}

2020B.editorial_text:
B. Brightness Begins
By nishkarsh

Hint 1
The final state of $$$i$$$th bulb (on or off) is independent of $$$n$$$.

Hint 2
The final state of the $$$i$$$th bulb tells us about the parity of number of divisors of $$$i$$$.

Solution
For any bulb $$$i$$$, its final state depends on the parity of the number of divisors of $$$i$$$. If $$$i$$$ has an even number of divisors, then bulb $$$i$$$ will be on; else it will be off. This translates to, if $$$i$$$ is not a perfect square, bulb $$$i$$$ will be on; else it will be off. So now the problem is to find the $$$k$$$th number which is not a perfect square. This can be done by binary searching the value of $$$n$$$ such that $$$n- \lfloor \sqrt{n} \rfloor = k$$$ or the direct formula $$$n$$$ = $$$\lfloor k + \sqrt{k} + 0.5 \rfloor$$$.
For the proof of the second formula you can refer this book page 141 E18

Code 1
#include <bits/stdc++.h>
using namespace std;
int main(){
int t;
cin >> t;
while(t--){
long long k, l = 1, r = 2e18;
cin >> k;
while(r-l > 1){
long long mid = (l+r)>>1;
long long n = mid - int(sqrtl(mid));
if(n >= k) r = mid;
else l = mid;
}
cout << r << "\n";
}
return 0;
}

Code 2
#include <bits/stdc++.h>
using namespace std;
int main(){
int t;
cin >> t;
while(t--){
long long k;
cin >> k;
cout << k + int(sqrtl(k) + 0.5) << "\n";
}
return 0;
}

2020C.editorial_text:
C. Bitwise Balancing
By P.V.Sekhar

Hint 1
Try to find some independent operations/combinations.

Hint 2
The expression is independent for each digit in binary representation

Solution
The first observation is that the expression $$$a$$$|$$$b$$$ - $$$a$$$&$$$c = d$$$ is bitwise independent. That is, the combination of a tuple of bits of $$$a, b, and\ c$$$ corresponding to the same power of 2 will only affect the bit value of $$$d$$$ at that power of 2 only.
This is because:

We are performing subtraction, so extra carry won't be generated to the next power of 2.

Any tuple of bits of $$$a$$$, $$$b$$$, and $$$c$$$ corresponding to the same power of 2 won't result in -1 for that power of 2. As that would require $$$a|b$$$ to be zero and $$$a$$$&$$$c$$$ to be one. The former condition requires the bit of $$$a$$$ to be zero, while the latter requires it to be one, which is contradicting.

Now, let us consider all 8 cases of bits of a, b, c and the corresponding bit value of d in the following table:
So, clearly, for different bits of $$$b, c,$$$ and $$$d$$$, we can find the value of the corresponding bit in $$$a$$$, provided it is not the case when bit values of $$$b, c,$$$ and $$$d$$$ are 1,0,0 or 0,1,1, which are not possible; so, in that case, the answer is -1.

Code
#include <bits/stdc++.h>
#define ll long long
using namespace std;

void solve() {
ll a = 0, b, c, d, pos = 1, bit_b, bit_c, bit_d, mask = 1;
cin >> b >> c >> d;
for (ll i = 0; i < 62; i++) {
if (b&mask) bit_b = 1;
else bit_b = 0;
if (c&mask) bit_c = 1;
else bit_c = 0;
if (d&mask) bit_d = 1;
else bit_d = 0;
if ((bit_b && (!bit_c) && (!bit_d)) || ((!bit_b) && bit_c && bit_d)) {
pos = 0;
break;
}
if (bit_b && bit_c) {
a += (1ll-bit_d)*mask;
} else {
a += bit_d*mask;
}
mask<<=1;
}
if (pos) {
cout << a << "\n";
} else {
cout << -1 << "\n";
}
}

int main() {
ll t;
cin >> t;
while (t--) {
solve();
}
}

2020D.editorial_text:
D. Connect the Dots
By P.V.Sekhar

Hint 1
The value of $$$d$$$ is very small.

Hint 2
Try using Disjoint Set Union (DSU).

Solution
The main idea is to take advantage of the low upper bound of $$$d_i$$$ and apply the Disjoint Set Union.
We will consider $$$dp[j][w]$$$, which denotes the number of ranges that contain the $$$j$$$ node in connection by the triplets/ranges with $$$w$$$ as $$$d$$$ and $$$j$$$ is not $$$a\ +\ k\ *\ d$$$, and $$$id[j][w]$$$, which denotes the node that represents an overall connected component of which $$$j$$$ node is part of for now.
The size of both $$$dp$$$ and $$$id$$$ is $$$max_j * max_w = (n) * 10 = 10\ n$$$.
We will maintain two other arrays, $$$Start_cnt[j][w]$$$ and $$$End_cnt[j][w]$$$, which store the number of triplets with $$$j$$$ as $$$a_i$$$ and $$$a_i+k_i*d_i$$$, respectively, and with $$$w$$$ as $$$d_i$$$, to help us maintain the beginning and end of ranges.
We will now apply Disjoint Set Union. For each $$$i$$$th triplet, we assume $$$a_i$$$ will be the parent node of the Set created by $$$a_i$$$, $$$a_i$$$ + $$$d_i$$$, ..., $$$a_i+k_i*d_i$$$.
The transitions of $$$dp$$$ are as follows: 
1) if $$$j \ge 10$$$ (max of $$$d_i$$$): for all $$$w$$$, $$$dp[j][w]$$$ are the same as $$$dp[j-w][w]$$$, just with some possible changes. These changes are due to $$$j$$$ being the start or the end of some triplet with $$$d_i$$$ as $$$w.$$$ So, let us start with $$$dp[j][w]$$$ as $$$Start_cnt[j][w] - End_cnt[j][w]$$$. If $$$dp[j-w][w]$$$ is non-zero, then perform a union operation (of DSU) between the $$$j$$$ node and $$$id[j-w][w]$$$, increment $$$dp[j][w]$$$ by $$$dp[j-w][w]$$$, and assign $$$id[j][w]$$$ as $$$id[j-w][w]$$$. This unites the ranges over the $$$j$$$ node.
2) if $$$j \lt 10$$$ (max of $$$d_i$$$): we do the same as above; rather than doing for all $$$w,$$$ we would restrict ourselves with $$$w$$$ from $$$0$$$ to $$$j-1$$$. 
The net time complexity = updation of $$$dp[j][w]$$$ value by $$$Start_cnt$$$ and $$$End_cnt$$$ + union operations due to union of $$$id[j-w][w]$$$ with $$$j$$$ over all $$$w$$$ + incrementing $$$dp$$$ values (by $$$dp[j-w][w]$$$) + copying $$$id$$$ values = $$$10\ n + 10\ nlogn + 10\ n + 10\ n= 10 nlogn + 30n$$$ (in worst case) = $$$O(max_d*n*logn)$$$.

Code
#include <bits/stdc++.h>
#define ll long long
using namespace std;
const ll N = 2e5+2;
const ll C = 10 + 1;

vector<ll> par(N), sz(N, 0);
vector<vector<ll>> dp(N, vector<ll> (C, 0)), ind(N, vector<ll> (C, 0)), start_cnt(N, vector<ll> (C, 0)), end_cnt(N, vector<ll> (C,0));

ll find_par(ll a) {
if (par[a] == a) return a;
return par[a] = find_par(par[a]);
}

void unite(ll a, ll b){
a = find_par(a), b = find_par(b);
if (a == b) return;
if (sz[b] > sz[a]) swap(a, b);
sz[a] += sz[b];
par[b] = a;
}

void reset(ll n) {
for (ll i = 1; i <= n; i++) {
par[i] = i;
sz[i] = 1;
for (ll j = 1; j < C; j++) {
dp[i][j] = start_cnt[i][j] = end_cnt[i][j] = 0;
ind[i][j] = i;
}
}
}

void solve() {
ll n, m, a, d, k;
cin >> n >> m;
reset(n);
for (ll i = 0; i < m; i++) {
cin >> a >> d >> k;
start_cnt[a][d]++;
end_cnt[a + k * d][d]++;
}
for (ll i = 1; i <= n; i++) {
for (ll j = 1; j < C; j++) {
dp[i][j] = start_cnt[i][j] - end_cnt[i][j];
if (i-j < 1) continue;
if (dp[i-j][j]) {
unite(ind[i-j][j], i);
ind[i][j] = ind[i-j][j];
dp[i][j] += dp[i-j][j];
}
}
}
ll ans = 0;
for (ll i = 1; i <= n; i++) {
if (find_par(i) == i) ans++;
}
cout << ans << "\n";
}

int main() {
ll t;
cin >> t;
while (t--) {
solve();
}
}

2020E.editorial_text:
E. Expected Power
By nishkarsh

Hint 1
Try to find the expected value of $$$f(S)$$$ rather than $$$(f(S))^2$$$.

Hint 2
Write the binary representation of $$$f(S)$$$ and find $$$(f(S))^2$$$.

Solution
Let the binary representation of the $$$Power$$$ be $$$b_{20}b_{19}...b_{0}$$$. Now $$$Power^2$$$ is $$$\sum_{i=0}^{20} \sum_{j=0}^{20} b_i b_j * 2^{i+j}$$$. Now if we compute the expected value of $$$b_ib_j$$$ for every pair $$$(i,j)$$$, then we are done.
We can achieve this by dynamic programming. For each pair $$$i,j$$$, there are only 4 possible values of $$$b_i,b_j$$$. For every possible value, we can maintain the probability of reaching it, and we are done.
The complexity of the solution is $$$O(n.log(max(a_i))^2)$$$.

Code
#include <bits/stdc++.h>
using namespace std;
int fast_exp(int b, int e, int mod){
int ans = 1;
while(e){
if(e&1) ans = (1ll*ans*b) % mod;
b = (1ll*b*b) % mod;
e >>= 1;
}
return ans;
}
const int mod = 1e9+7;
const int bits = 11;

int inv(int n){
return fast_exp(n,mod-2,mod);
}

const int inverse_1e4 = inv(10000);
int dp[bits][bits][2][2];
void transition(int a, int p){
p = (1ll*p*inverse_1e4) % mod;
int negp = (mod+1-p) % mod;
int bin[bits];
for(int i = 0; i < bits; i++){
bin[i] = a&1;
a >>= 1;
}
for(int i = 0; i < bits; i++){
for(int j = 0; j < bits; j++){
int temp[2][2];

for(int k : {0,1}) for(int l : {0,1}) temp[k][l] = (1ll*dp[i][j][k][l]*negp + 1ll*dp[i][j][k^bin[i]][l^bin[j]]*p) % mod;

for(int k : {0,1}) for(int l : {0,1}) dp[i][j][k][l] = temp[k][l];
}
}
}
int main() {
int t;
cin >> t;
while(t--){
int n;
cin >> n;
int a[n],p[n];
for(int i = 0; i < n; i++) cin >> a[i];
for(int i = 0; i < n; i++) cin >> p[i];
for(int i = 0; i < bits; i++) for(int j = 0; j < bits; j++) dp[i][j][0][0] = 1;
for(int i = 0; i < n; i++) transition(a[i],p[i]);
int ans = 0;
for(int i = 0; i < bits; i++){
for(int j = 0; j < bits; j++){
int pw2 = (1ll<<(i+j)) % mod;
ans += (1ll*pw2*dp[i][j][1][1]) % mod;
ans %= mod;
for(int k : {0,1}) for(int l : {0,1}) dp[i][j][k][l] = 0;
}
}
cout << ans << "\n";
}
return 0;
}

2020F.editorial_text:
F. Count Leaves
By nishkarsh

Hint 1
$$$f$$$ satisfies a special property for fixed d.

Answer
$$$f$$$ is multiplicative i.e. $$$f(x.y)$$$ = $$$f(x) * f(y)$$$ if $$$x,y$$$ are coprime, for fixed d.

Solution
It can be observed that the number of leaves is equal to the number of ways of choosing $$$d$$$ integers $$$a_0,a_1,a_2...a_d$$$ with $$$a_d = n$$$ and $$$a_i divides a_{i+1}$$$ for all $$$(0 \le i \le d-1)$$$.
Lets define $$$g(n) = f(n,d)$$$ for given $$$d$$$. It can be seen that the function $$$g$$$ is multiplicative i.e. $$$g(p*q) = g(p)*g(q)$$$ if $$$p$$$ and $$$q$$$ are coprime.
Now, lets try to calculate $$$g(n)$$$ when $$$n$$$ is of the form $$$p^x$$$ where $$$p$$$ is a prime number and $$$x$$$ is any non negative integer. From the first observation, we can say that here all the $$$a_i$$$ will be a power of $$$p$$$. Therefore $$$a_0,a_1,a_2...a_d$$$ can be written as $$$p^{b_0},p^{b_1},p^{b_2}...p^{b_d}$$$. Now we just have to ensure that $$$0 \le b_0 \le b_1 \le b_2 ... \le b_d = x$$$. The number of ways of doing so is $$$\binom{x+d}{d}$$$.
Now, lets make a dp (inspired by the idea of the dp used in fast prime counting) where $$$dp(n,x) = \sum_{i=1, spf(i) \gt = x}^{n} g(i)$$$. Here $$$spf(i)$$$ means smallest prime factor of $$$i$$$.
$$$ dp(x, p) = \begin{cases} 0 & \text{if } x = 0 \\ 1 & \text{if } p \gt x \\ dp(x, p+1) & \text{if } p \text{ is not prime} \\ \sum\limits_{i=0 \, \text{to} \, p^i \le x} dp\left(\lfloor{\frac{x}{p^i}} \rfloor, p+1\right) f(p^{ik}, d) & \text{otherwise} \end{cases} $$$
Our required answer is $$$dp(n,2)$$$.
The overall complexity of the solution is $$$O(n^{\frac{2}{3}})$$$.

