for(ll i=1;i<=n;i++){
for(ll j=1;j<=n;j++){
if(r[i]<l[j]){
ll found=lft[i]+rght[j];
ll now=nCr(found,lft[i],MOD)*(l[j]-r[i]);
now%=MOD;
ll remaining=n-found-2;
ans=(ans+now*power[remaining])%MOD;
}
}
}
cout<<ans<<nline;
return; 
} 
