for(int i = 0; i < n; i++)
AddBack(i);
if(cnt[0] <= cnt[2]) {
Fix(0);
Fix(2);
} else {
Fix(2);
Fix(0);
}
cout << swaps.size() << endl;
for(auto [i, j]: swaps)
