if (d[t] == INF) break;
int addflow = maxflow - flow;
for (int v = t; v != s; v = p[v]) {
int pv = p[v]; size_t pr = p_rib[v];
addflow = min(addflow, g_mcmf[pv][pr].u - g_mcmf[pv][pr].f);
