for(int i=1;i<=n;i++)
{
s.insert({d[i],i});
}
int ans=2;
queue<int> q;
while(!s.empty()&&(*s.begin()).first==0)
{
while(!s.empty()&&(*s.begin()).first==0)
{
int k=(*s.begin()).second;
ans=max(ans,v[k]+2);v[r[k]]+=v[k];
auto it=s.find({d[r[k]],r[k]});
d[r[k]]--;
if(it!=s.end())
{
s.erase(it);
q.push(r[k]);
}
s.erase(s.begin());
}
while(!q.empty())
s.insert({d[q.front()],q.front()}),q.pop();
}
cout<<ans<<'\n';
}
return 0;
