int up = 1 << L;
vector<int> dp(up);
for(int i = 0; i < n; i++) dp[i] = S(n, i + 1);
for(int j = 0; j < L; j++) {
for(int i = 0; i < up; i++) {
if(i >> j & 1) dp[i] ^= dp[i ^ (1 << j)];
}
