#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
#define debug(x) cout << #x << " = " << x << "\n";
#define vdebug(a) cout << #a << " = "; for(auto x: a) cout << x << " "; cout << "\n";
mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());
int uid(int a, int b) { return uniform_int_distribution<int>(a, b)(rng); }
ll uld(ll a, ll b) { return uniform_int_distribution<ll>(a, b)(rng); }

template <class T> struct SegTree{
vector<T> seg;
int n;
const T ID = {INT_MAX, -INT_MAX};

T cmb(T a, T b){
array<int, 2> res;
res[0] = min(a[0], b[0]);
res[1] = max(a[1], b[1]);
return res;
}

SegTree(int _n){
n = 1;
while (n < _n) n *= 2;
seg.assign(2 * n + 1, ID);
}

void set(int pos, T val){
seg[pos + n] = val;
}

void build(){
for (int i = n - 1; i >= 1; i--) seg[i] = cmb(seg[2 * i], seg[2 * i + 1]);
}

void upd(int v, int tl, int tr, int pos, T val){
if (tl == tr){
seg[v] = val;
} else {
int tm = (tl + tr) / 2;
if (pos <= tm) upd(2 * v, tl, tm, pos, val);
else upd(2 * v + 1, tm + 1, tr, pos, val);
seg[v] = cmb(seg[2 * v], seg[2 * v + 1]);
}
}

void upd(int pos, T val){
upd(1, 0, n - 1, pos, val);
}

T query(int v, int tl, int tr, int l, int r){
if (l > r) return ID;
if (l == tl && r == tr) return seg[v];
int tm = (tl + tr) / 2;
T res = query(2 * v, tl, tm, l, min(tm, r));
res = cmb(res, query(2 * v + 1, tm + 1, tr, max(l, tm + 1), r));
return res;
}

T query(int l, int r){
return query(1, 0, n - 1, l, r);
}
};

void solve(){
int n, k;
cin >> n >> k;

vector<int> a(n);
for (int &x : a) cin >> x;

vector<vector<int>> p(n + 1);
for (int i = 0; i < n; i++)
p[a[i]].push_back(i);

vector<array<int, 2>> stk;
vector<int> small_l(n, -1), small_r(n, n), big_l(n, -1), big_r(n, n);

for (int i = 0; i < n; i++){
while (stk.size() && a[i] <= stk.back()[0])
stk.pop_back();

if (stk.size())
small_l[i] = stk.back()[1];
stk.push_back({a[i], i});
}

stk.clear();
for (int i = n - 1; i >= 0; i--){
while (stk.size() && a[i] >= stk.back()[0])
stk.pop_back();

if (stk.size())
big_r[i] = stk.back()[1];
stk.push_back({a[i], i});
}

ll ans = 0;
SegTree<array<int, 2>> seg_small(n), seg_big(n);

for (int x = 1; x <= n; x++){
int y = k - x;
if (y > n){
for (int pos : p[x])
seg_small.upd(pos, {pos, pos});
continue;
}

vector<int> pre(p[y].size());
for (int i = 0; i < p[y].size(); i++){
if (i > 0)
pre[i] += pre[i - 1];

int r = big_r[p[y][i]] - 1;
if (i < p[y].size() - 1)
r = min(r, p[y][i + 1] - 1);
pre[i] += r - p[y][i] + 1;
}

vector<int> first(p[x].size()), last(p[y].size());
for (int i = 0; i < p[x].size(); i++)
first[i] = seg_small.query(p[x][i], n - 1)[0];

for (int i = 0; i < p[y].size(); i++)
last[i] = seg_big.query(0, p[y][i])[1];

int prev = -1;
for (int i = 0; i < p[x].size(); i++){
int l = p[x][i];
int l_min = small_l[l] + 1;
l_min = max(l_min, prev + 1);
prev = l;

int nxt = upper_bound(p[y].begin(), p[y].end(), l) - p[y].begin();
if (nxt == p[y].size())
continue;

int lo = nxt, hi = p[y].size();
while (lo < hi){
int mid = (lo + hi) / 2;

int pos = p[y][mid];
if (first[i] <= last[mid])
hi = mid;
else
lo = mid + 1;
}

lo--;
if (lo < nxt)
continue;

int res = pre[lo];
if (nxt > 0)
res -= pre[nxt - 1];

ans += 1LL * (l - l_min + 1) * res;
}

for (int pos : p[x])
seg_small.upd(pos, {pos, pos});
for (int pos : p[y])
seg_big.upd(pos, {pos, pos});
}

cout << ans << "\n";
}

int main(){
ios::sync_with_stdio(false);
cin.tie(0);
cout.tie(0);

int t;
cin >> t;
while (t--) solve();
}

2069E.editorial_text:
2069E - A, B, AB and BA
Firstly, let's find the solution that maximizes the number of used blocks of length $$$2$$$ (AB and BA). Each used block of length $$$2$$$ frees us one A and B, so we don't lose anything.
Secondly, since we don't have AA and BB, any pair of equal neighboring characters will be split in-between in any possible partition. So, let's split them at the start. As a result, we'll get blocks with alternating characters of four types: 

ABA..A: if it's length $$$l$$$ it can be split in $$$x$$$ AB-s and $$$y$$$ BA-s for any $$$x + y \le \frac{l}{2}$$$. For example: A|BA|BA, AB|B|BA or AB|AB|A; 
BAB..B: practically the same as the previous, so let's just count the total number of blocks we can get from the first two types as $$$tot$$$; 
ABA..B: it can be split in $$$\frac{l}{2}$$$ of AB, but if we need at least one BA the total number of blocks will reduce to $$$\frac{l}{2} - 1$$$. For example: AB|AB|AB, but AB|A|BA|B; 
BAB..A: the same case, but favors BA-s instead. 
So, let's split ABA..B into AB and BAB..A into BA as much as we can. As a result, one of three cases will follow: 

We spent all $$$ab$$$: then remaining ABA..B blocks will be split into BA. We lose one pair of A and B for each ABA..B block, so it's optimal to reduce the number of remaining ABA...B, so it's optimal to split shortest ABA...B-s into AB-s at the first step. 
We spent all $$$ba$$$: remaining BAB..A blocks will be split into AB. The case is the same as previous and gives the same greedy: split shortest BAB..A-s into BA-s at the first step. 
There are no AB..B and BA..A left. Only odd-length blocks left (the first two types}, so it doesn't matter how to split it. In total we'll get $$$\min{(ab + ba, tot)}$$$ more blocks of length $$$2$$$. 
Note that cases $$$1$$$ and $$$2$$$ will lead to either case $$$3$$$ or zeroing both $$$ab$$$ and $$$ba$$$, but if both $$$ab = 0$$$ and $$$ba = 0$$$ we'll also get $$$\min{(ab + ba, tot)} = 0$$$ extra blocks from the first two types of alternating strings. In other words, there are not so much casework as it seems.
In total, the strategy is the following: 

split AB..B-s into AB in increasing order of lengths; 
split BA..A-s into BA in increasing order of lengths; 
split remaining AB..B-s into BA in any order; 
split remaining BA..A-s into AB in any order; 
calculate extra pairs you'll get using the formula $$$\min{(ab + ba, tot)}$$$. 
check that you have enough $$$a$$$ and $$$b$$$ to cover remaining A-s and B-s. 
Total complexity is $$$O(|s| \log{|s|})$$$.

2070F.editorial_text:
2070F - Friends and Pizza
Before solving this problem, I highly recommend that you learn Sum over Subsets Dynamic Programming (aka SOS DP), if you don't know it yet. For example, you can use this CF blog, it has a great explanation of SOS DP: https://codeforces.com/blog/entry/45223
First, we will somewhat change the problem. The original problem wants us to consider all pairs of friends $$$(i, j)$$$ where $$$1 \le i \lt j \le n$$$; but instead, we will consider all pairs of friends where $$$1 \le i, j \le n$$$ (so, $$$i$$$ can be greater than $$$j$$$ and can even be equal to $$$j$$$). After solving this modified version, we can "subtract" all pairs where $$$i=j$$$ (since there are only $$$O(m)$$$ of them) and divide all the answers by $$$2$$$ to get rid of the pairs where $$$i \gt j$$$ (they are symmetrical to $$$i \lt j$$$, so they yield the same answer). From now on, we consider only the version where we need to count all pairs of friends.
For every friend, we can transform the string $$$s_i$$$ into a bit mask which shows what pizzas that friend likes. Then, checking if the friends quarrel and which pizzas they will eat can be done by bit operations on their masks: if the bitwise AND of their masks and the mask of odd-size pizzas is non-zero, there is at least one odd-size pizza they both like, so they will quarrel; and the mask of pizzas they will eat is just the bitwise OR of their masks.
So, if for each mask, we want to calculate the number of pairs of friends which don't quarrel and result in exactly that mask being eaten, we can run the following code:
for(int i = 0; i < m; i++)
for(int j = 0; j < m; j++)
{
if((mask[i] & mask[j] & mask_of_odd_pizzas) == 0)
ans[mask[i] | mask[j]]++; 
}
Or, if for each mask, we calculate $$$c_i$$$ as the number of friends having that mask, we can rewrite it as follows:
for(int i = 0; i < (1 << n); i++)
for(int j = 0; j < (1 << n); j++)
{
if((i & j & mask_of_odd_pizzas) == 0)
ans[i | j] += c[i] * c[j]; 
}
Let's first consider two special instances of this problem, and then we'll combine their solutions to solve the general case.
Instance 1. What if all pizzas have even sizes?
Then our mask of add pizzas is $$$0$$$, so friends will never quarrel. In this case, we can rewrite the "naive" code as follows:
for(int i = 0; i < (1 << n); i++)
for(int j = 0; j < (1 << n); j++)
{
ans[i | j] += c[i] * c[j]; 
}
This is an OR convolution of the sequence $$$c$$$ with itself, and it can be calculated much faster than $$$O(4^n)$$$. When dealing with regular convolutions, a fast way to calculate them is the following one:

Transform the sequences using FFT or NTT. 
Multiply the corresponding elements of the transformed sequences. 
Perform the inverse transformation. 
OR convolution can be done in the same way, but instead of FFT or NTT, we will use SOS DP. So, an OR convolution of two sequences $$$a$$$ and $$$b$$$ looks like that:
A = sos_dp(a);
B = sos_dp(b);
for(int i = 0; i < (1 << n); i++)
C[i] = A[i] * B[i];
c = inverse_sos_dp(C);
Why does SOS DP do the trick? $$$C_i = A_i \cdot B_i$$$ means that $$$C_i$$$ is the sum of $$$a_j \cdot b_k$$$ over all $$$j$$$ and $$$k$$$ that are submasks of $$$i$$$. For some pairs $$$(j, k)$$$, their bitwise OR is exactly $$$i$$$; but for others, their bitwise OR is a submask of $$$i$$$. So, actually, $$$C_i$$$ is the sum over submasks of the sequence we need to obtain, so by applying inverse SOS DP (the transformation which returns the sequence by its sums over submasks), we get exactly what we need.
Quick note about inverse SOS DP — it is done the same as the regular SOS DP, but with subtractions instead of additions. You can prove it by trying to "rollback" the changes the regular SOS DP does to a sequence.
Okay, the instance when all pizzas have even size is done. Next, we have
Instance 2. What if all pizzas have odd sizes?
The "naive" code would look like that:
for(int i = 0; i < (1 << n); i++)
for(int j = 0; j < (1 << n); j++)
{
if((i & j) == 0) a[i | j] += c[i] * c[j]; 
}
Unfortunately, this is much trickier. This is called Fast Subset Convolution, and to do it faster, we have to add another dimension to our sequence. Now suppose we want to get the FSC of sequences $$$a$$$ and $$$b$$$, and the resulting sequence is named $$$c$$$.
If the bitwise OR of $$$i$$$ and $$$j$$$ is $$$k$$$, and the bitwise AND of $$$i$$$ and $$$j$$$ is $$$0$$$, then $$$popcount(k)$$$ (the number of bits set to $$$1$$$ in $$$k)$$$ is equal to $$$popcount(i) + popcount(j)$$$. So, the value of $$$c_k$$$ can be represented as the sum of $$$a_i \cdot b_j$$$ over all such $$$i, j$$$ that the bitwise OR of $$$i$$$ and $$$j$$$ is $$$k$$$, and $$$popcount(k) = popcount(i) + popcount(j)$$$.
Let's transform our given sequences of length $$$2^n$$$ into two-dimensional matrices of size $$$(n + 1) \times (2^n)$$$. Let $$$a'_{x,i}$$$ be $$$0$$$ if $$$popcount(i) \ne x$$$, or $$$a_i$$$ if $$$popcount(i) = x$$$. Similarly, we denote $$$b'_{y,j}$$$ based on $$$b$$$.
Okay, now let's try to make it so that, in the resulting convolution, the product $$$a'_{x,i} \cdot b'_{y,j}$$$ ends up in the cell $$$c'_{x+y, i \lor j}$$$, where $$$\lor$$$ denotes bitwise OR. To do this, let's evaluate the $$$k$$$-th row of $$$c'$$$ as the following sum: $$$\sum_{i=0}^k \text{ORConvolution}(a'_i, b'_{k-i})$$$. The OR Convolution will make sure that, for every pair of $$$i, j$$$, $$$a_i \cdot b_j$$$ ends up in some cell of the form $$$c'_{k, i \lor j}$$$, and to verify that their bitwise AND is $$$0$$$, we can check that $$$k = popcount(i \lor j)$$$. So, the resulting value of $$$c_i$$$ we want to get is equal to $$$c'_{popcount(i),i}$$$.
This Fast Subset Convolution can be done in $$$O(n^2 2^n)$$$ if you apply SOS DP to every row of $$$a'$$$ and $$$b'$$$ to get matrices with sums over submasks in each row (let's call them $$$A$$$ and $$$B$$$), calculate $$$C_{k,i} = \sum \limits_{j=0}^k A_{j,i} \cdot B_{k-j,i}$$$, and then apply Inverse SOS DP to each row of $$$C$$$ to get the matrix $$$c'$$$.
Okay, now back to the original problem.
Instance 3. What if some pizzas have odd size, and others have even size?
We need to make a convolution for which some bits (represending even-sized pizzas) work as in OR Convolution, but other bits (representing odd-sized pizzas) work as in Fast Subset Convolution. 
The key idea is that we can modify Fast Subset Convolution so that it tracks only the number of bits representing odd-sized pizzas. So, let's define $$$F(x)$$$ as the number of bits representing odd-sized pizzas in $$$x$$$. So, when we transform the given sequences $$$a$$$ and $$$b$$$ to the matrices $$$a'$$$ and $$$b'$$$, we set $$$a'_{x,i}$$$ to $$$0$$$ if $$$F(i) \ne x$$$, or $$$a_i$$$ if $$$F(i) = x$$$. And our matrices will have size $$$(p+1) \times (2^n)$$$, where $$$p$$$ is the number of odd-sized pizzas. Note that, in our problem, the sequences $$$a$$$ and $$$b$$$ are the same, so the matrix $$$b'$$$ is actually the same as $$$a'$$$.
Similarly, to get the sequence $$$c$$$ from the matrix $$$c'$$$, we set $$$c_i = c'_{F(i), i}$$$.
This modification of Fast Subset Convolution works in $$$O(p \cdot n \cdot 2^n)$$$. Since $$$p \le n$$$, we get a solution working in $$$O(n^2 2^n + mn)$$$ (the $$$O(mn)$$$ summand comes from processing the friends and converting them into masks).

2071A.editorial_text:
2071A - Игра никогда не заканчивается

Hints
Hint 1
When Fofo is the spectator of the first match, what is the earliest subsequent game in which he will spectate again?

Hint 2
Suppose Sosai wins the first game. What becomes clear?

Solution
Once the winner of the first match is decided, the rest of the game is completely predictable.
For example, if Hohai wins the first match which Fofo spectated, we can see that:
$$$ {} $$$ $$$ \text{Sosai} \overset{\text{Spectator of 1st: Fofo}}{\longleftrightarrow} \text{Hohai} $$$ $$$ \text{Fofo} \overset{\text{Spectator of 2nd: Sosai}}{\longleftrightarrow} \text{Hohai} $$$ $$$ \text{Fofo} \overset{\text{Spectator of 3rd: Hohai}}{\longleftrightarrow} \text{Sosai} $$$ $$$ \text{Hohai} \overset{\text{Spectator of 4th: Fofo}}{\longleftrightarrow} \text{Sosai} $$$ $$$ \text{Hohai} \overset{\text{Spectator of 5th: Sosai}}{\longleftrightarrow} \text{Fofo} $$$ $$$ \text{Sosai} \overset{\text{Spectator of 6th: Hohai}}{\longleftrightarrow} \text{Fofo} $$$ $$$ \text{Sosai} \overset{\text{Spectator of 7th: Fofo}}{\longleftrightarrow} \text{Hohai} $$$
No matter who wins in the second match, Hohai won't be able to continue playing in the third match (even if he wins the second match) since he has already played two times in a row. Similarly, Fofo won't be able to play in the fourth match because he has already played twice in a row, regardless of the match result.
As a result, Fofo won't be able to spectate in the $$$k$$$-th match for any $$$k$$$ of the form $$$3x + 1$$$.
The overall time complexity is: $$$O(1)$$$.

