auto get = [&](int64_t x) {
int ret = 0;
while (true) {
if (x <= n * 2) {
ret ^= a[x];
break;
}
ret ^= p;
if ((x / 2 - n) % 2 == 0) {
break;
}
x /= 2;
}
return ret;
};
cout << get(l) << "\n";
}
int main() {
ios::sync_with_stdio(0), cin.tie(0);
int tt = 1;
