for (int i = 0; i < n - 1; i++) {
int u, v;
cin >> u >> v;
u--, v--;
G[u].push_back(v);
G[v].push_back(u);
}

vector<int> dist(n), p(n);
function<void(int, int)> dfs = [&](int now, int par) {
p[now] = par;
for (int i : G[now]) {
if (i != par) {
dist[i] = dist[now] + 1;
dfs(i, now);
}
}
};

dist[0] = 0;
dfs(0, -1);
int x = max_element(dist.begin(), dist.end()) - dist.begin();
dist[x] = 0;
dfs(x, -1);
int y = max_element(dist.begin(), dist.end()) - dist.begin();

if (dist[y] == n - 1) {
cout << -1 << '\n';
} else {
vector<int> on_diameter(n);
int now = y;
while (now != -1) {
on_diameter[now] = 1;
now = p[now];
}
