for (int u = 0; u < n; u++) {
for (int v : G[u]) {
if (on_diameter[u] && !on_diameter[v]) {
a = p[u], b = u, c = v;
break;
}
}
if (a != -1)
break;
}
cout << a + 1 << ' ' << b + 1 << ' ' << c + 1 << '\n';
}
