dp[i] = dp[i - 1], q[a[i]].emplace_back(i);
if (q[a[i]].size() > a[i]) q[a[i]].pop_front();
if (q[a[i]].size() == a[i]) dp[i] = max(dp[i], dp[q[a[i]].front() - 1] + a[i]);
}
printf("%d\n", dp[n]);
}
}

