while(x!=kk){
if (x>y) ans.push_back(2),x-=y,y*=2;
else ans.push_back(1),y-=x,x*=2;
}
cout<<ans.size()<<"\n";
while(!ans.empty()) cout<<ans.back()<<' ',ans.pop_back();
cout<<"\n";
}
return 0;
}

