while(sz(ans) < max_k){
int tmp = sz(ans);
auto& v = g[lex_min[tmp]];
FOR(i,tmp,sz(v)) ans.pb(v[i]);
}
assert(sz(ans) == max_k);
cout << ans << "\n";
}

