for(int i = 1; i<=n; i++){
int x = a[i];
vector<int> next;
for(auto &num : divs[x]){
cnt[num]++;
if(cnt[num] != i)ans = max(ans, cnt[num]);
else if(!vis[num]){
next.pb(num);
vis[num] = 1;
}
}

for(auto &num : max_nums){
if(cnt[num] != i){
ans = max(ans, cnt[num]);
vis[num] = 0;
} else next.pb(num);
}
max_nums = next;
cout<<ans<<" \n"[i == n];
}
}

