swp = true;
}
for (int l = MAXL - 1; l >= 0; l--) {
if (lvl[p[l][a]] >= lvl[b]) {
a = p[l][a];
}
}
if (a == b) {
return {a, -1, -1};
}
if (swp) {
swap(a, b);
}
for (int l = MAXL - 1; l >= 0; l--) {
if (p[l][a] != p[l][b]) {
a = p[l][a];
b = p[l][b];
}
}
return {p[0][a], a, b};
}

ll solve_same_layer(int l, int r) {
assert(p[0][l] == p[0][r]);
ll res =
(pfx[r] -
((nxt_occ(r + 1, a[l]) - occ[a[l]].begin()) % 2 == 1 ? a[l] : 0)) -
(pfx[l] -
((nxt_occ(l, a[l]) - occ[a[l]].begin() + 1) % 2 == 1 ? a[l] : 0));
if ((nxt_occ(r + 1, a[l]) - nxt_occ(l, a[l])) % 2 == 1) {
res += a[l];
}
return res;
}

void precompute() {
for (int i = 0; i <= n; i++) {
occ[i].clear();
adj[i].clear();
pfx[i] = sfx[i] = sm_pfx[i] = sm_sfx[i] = 0;
}
for (int i = 1; i <= n; i++) {
occ[a[i]].push_back(i);
}
vector<int> stk;
stk.push_back(0);
for (int i = 1; i <= n; i++) {
if (!is_first_occ(i)) {
assert(!stk.empty() && a[stk.back()] == a[i]);
stk.pop_back();
}
assert(!stk.empty());
add_edge(stk.back(), i);
if (!is_last_occ(i)) {
stk.push_back(i);
}
}

for (int u = n; u >= 0; u--) {
{
ll prv = 0;
for (int i = 0; i < (int)adj[u].size(); i++) {
int v = adj[u][i];
auto ptr = nxt_occ(v, a[v]);
pfx[v] =
prv + ((ptr - occ[a[v]].begin() + 1) % 2 == 1 ? a[v] : 0);
if (!adj[v].empty()) {
prv += pfx[adj[v].back()];
}
if (is_last_occ(v)) {
prv += occ[a[v]].size() % 2 == 1 ? a[v] : 0;
}
}
}
{
ll prv = 0;
for (int i = (int)adj[u].size() - 1; i >= 0; i--) {
int v = adj[u][i];
auto ptr = nxt_occ(v, a[v]);
if (!adj[v].empty()) {
prv += sfx[adj[v][0]];
}
sfx[v] = prv + ((occ[a[v]].end() - ptr) % 2 == 1 ? a[v] : 0);
if (is_first_occ(v)) {
prv += occ[a[v]].size() % 2 == 1 ? a[v] : 0;
}
}
}
}

dfs(0);
}

void init(int _n, int _q, vector<int> _a) {
n = _n;
q = _q;
for (int i = 1; i <= n; i++) {
a[i] = _a[i - 1];
}
precompute();
}

ll query(int l, int r) {
if (l == r) {
return a[l];
}
auto [lca, lc, rc] = get_lca(l, r);
assert(lca != r);
if (lca == l) {
ll ans = sm_pfx[r] - sm_pfx[l] + a[l];
return ans;
} else if (lc == l) {
ll ans = sm_pfx[r] - sm_pfx[rc];
ans += solve_same_layer(l, rc);
return ans;
} else {
ll ans = sfx[l] + sm_sfx[p[0][l]] - sm_sfx[lc] + sm_pfx[r] - sm_pfx[rc];
ans += solve_same_layer(*nxt_occ(lc + 1, a[lc]), rc);
return ans;
}
}

} // namespace solution

int main() {
ios::sync_with_stdio(0), cin.tie(0);
int t;
cin >> t;
while (t--) {
int n, q;
cin >> n >> q;
vector<int> a(n);
for (int i = 0; i < n; i++) {
cin >> a[i];
}

solution::init(n, q, a);
ll prv_ans = 0;
while (q--) {
int l, r;
cin >> l >> r;
auto decode = [&](int x) { return (x - 1 + prv_ans) % n + 1; };
l = decode(l);
r = decode(r);
if (l > r) {
swap(l, r);
}
ll ans = solution::query(l, r);
cout << ans << ' ';
prv_ans = ans;
}
cout << '\n';
}
return 0;
}

2162A.editorial_text:
2162A - Beautiful Average
Idea: wakanda-forever Preparation: wakanda-forever

Solution
Let's say we have a sequence of numbers with an average equal to $$$k$$$.
Adding a number greater than $$$k$$$ increases the average, while adding a smaller one decreases it.
Therefore, the maximum average subarray is formed by taking the maximum element, since including anything smaller would only lower the average.
Hence, the final answer is the maximum element of the given array.
Time Complexity: $$$O(n)$$$ per testcase.

