g[u].push_back(v);
g[v].push_back(u);
}

vector<int> dep(n), par(n), ch(n);
auto dfs = [&](auto self, int c, int p) -> void{
if (p != -1)
dep[c] = dep[p] + 1;
par[c] = p;

for (int x : g[c]){
if (x == p) continue;

self(self, x, c);
ch[c]++;
}
