cin >> a[i];
if(a[0] == -1)
a[0] = a[n-1];
if(a[n-1] == -1)
a[n-1] = a[0];
for(int i=0; i<n; i++)
if(a[i] == -1)
a[i] = 0;
cout << abs(a[n-1] - a[0]) << '\n';
for(int i=0; i<n; i++)
cout << a[i] << " \n"[i == n-1];
}

