for(auto &i : a) {
cin >> i;
}

int cnt = 0;
for(int i = 0; i < n; i++) {
cnt += (a[i] % 2 != (i + 1) % 2);
}

cout << (cnt == 0 || cnt == n? "YES" : "NO") << '\n';
}

