dp[a[i]] = 1;
}

for(int i = 1; i <= n; i++) {
for(int j = i; j <= n; j += i) {
dp[j] = min(dp[j], dp[i] + dp[j / i]);
}
}

for(int i = 1; i <= n; i++) {
if(dp[i] == 1e9) {
dp[i] = -1;
}
