g[u].push_back(v);
g[v].push_back(u);
}
if( a[u] && !a[v] ) g2[u].push_back(v);
if( a[v] && !a[u] ) g2[v].push_back(u);
}
queue <int> q;

for(int i = 1; i <= n; i++) {
if(!cnt[i] && !a[i]) {
cout << "NO\n";
return;
}
}
for(int i = 1; i <= n; i++) {
if(a[i] && !used[i]) {
dfs(i, 0);
if(sz[i] % 2 == 0) {
cout << "NO\n";
return;
}
}
}
for(int i = 1; i <= n; i++) {
if(a[i] && !bad[i]) {
q.push(i);
}
}
cout << "YES\n";
int zero[n + 5];

for( int i = 1; i <= n; i ++ ){
zero[i] = 0;

if( !a[i] && cnt[i] % 2 ) cout << i << ' ';
else if( !a[i] ) zero[i] = 1;
}
while(!q.empty()) {
int v = q.front(); q.pop();
cout << v << ' ';
for(int to : g2[v]){
if(zero[to]) cout << to << ' ', zero[to] = 0;
}
for(int to : e[v]) {
bad[to]--;
if(bad[to] == 0) q.push(to);
