int s = 0, ok = 0, id = 0;
par[v] = p; ord.push_back(v);

for( auto to : g[v] )
{
if( to == p ) continue;

dfs(to, v);
if(!flag) return;

if( dp[to] == 1 || dp[to] == 3 )
{
s ^= a[to];

if( dp[to] == 3 && a[to] == 1 )
{
if( !ok )
{
ok = 1;
id = to;
}
}
if( dp[to] == 3 && id != to ) dp[to] = 1;
}
}
if( !ok && s == a[v] && (s + a[p]) % 2 == a[v] )
{
flag = 0;
return;
}
if( s != a[v] || ok )
{
if( s == a[v] ) must[v][1] = {id, 2};
else if(ok) must[v][1] = {id, 1};

dp[v] = 1;
}
s = (s + a[p]) % 2;

if( s != a[v] || ok )
{
if( s == a[v] ) must[v][2] = {id, 2};
else if(ok) must[v][2] = {id, 1};

dp[v] += 2;
}
}
void dfs2( int v, int tp )
{
dp[v] = tp, used[v] = 1;
pair <int, int> p = must[v][tp];
if( p.first != 0 ) dfs2(p.first, p.second);
}
void solve()
{
cin >> n;
flag = 1;

// dp[v] = 1, if p[v] before v
// dp[v] = 2, if v before p[v]

for( int i = 1; i <= n; i ++ )
{
cin >> a[i];
a[i] %= 2;

must[i][1] = must[i][2] = {0, 0};
dp[i] = cnt[i] = used[i] = 0;
g[i].clear(), g2[i].clear();
}
for( int i = 1; i < n; i ++ )
{
cin >> x >> y;

g[x].push_back(y);
g[y].push_back(x);
}
ord.clear();
dfs(1);

if( !flag )
{
cout << "No\n";
return;
}
cout << "Yes\n";

for( auto i : ord )
{
if( !used[i] )
{
if( dp[i] == 3 ) dfs2(i, 1);
else dfs2(i, dp[i]);
}
}
for( int v = 2; v <= n; v ++ )
{
if( dp[v] == 1 ) cnt[v] ++, g2[par[v]].push_back(v);
else cnt[par[v]] ++, g2[v].push_back(par[v]);
}
queue <int> q;

for( int i = 1; i <= n; i ++ )
{
if( cnt[i] == 0 ) q.push(i);
}
while( !q.empty() )
{
int v = q.front();
q.pop(); cout << v << ' ';

for( auto to : g2[v] )
{
cnt[to] --;
if( !cnt[to] ) q.push(to);
}
}
cout << '\n';
}
int main()
{
ios_base::sync_with_stdio(0);

int t; cin >> t;
while(t --) solve();
}

