By Leftist_G.

#include <bits/stdc++.h>
#define fr1(i, a, b) for (int i = a; i <= b; i++)
#define fr2(i, a, b) for (int i = a; i >= b; i--)
using namespace std;
const int N = 1e5 + 10;
const int mod = 998244353;
int tc;
int n;
int a[N];
int dp[N];
int kmp[N];
void add(int & x, int y) {
x += y;
if (x >= mod) x -= mod;
}
void solve() {
cin >> n;
fr1(i, 1, n) cin >> a[i];
dp[0] = 1;
fr1(i, 1, n) dp[i] = 0;
fr1(i, 1, n) {
kmp[i] = i + 1;
int poi = i + 1;
fr2(j, i - 1, 1) {
while (a[j] != a[poi - 1] && poi != i + 1) poi = kmp[poi];
if (a[j] == a[poi - 1]) poi--;
kmp[j] = poi;
}
fr2(j, i, 1) {
if (kmp[j] == i + 1) add(dp[i], dp[j - 1]);
}
}
cout << dp[n] << '\n';
}
int main() {
ios::sync_with_stdio(false);
cin >> tc;
while (tc--) solve();
}

