By yanghanyv.

#include <bits/stdc++.h>
#define ll long long
using namespace std;
const int N=2e5+5;
const int M=4e5+5;
int t,n,m,fa[M];
ll s[M],ans;
vector<int> w[N],v[N];
void init(){
for(int i=1;i<=n;i++){
w[i].clear();
v[i].clear();
}
for(int i=0;i<=(n-1)*(m-1);i++){
fa[i]=i;
s[i]=0;
}
ans=0;
}
int idx(int x,int y){
return x>=1&&x<n&&y>=1&&y<m?(x-1)*(m-1)+y:0;
}
int find(int x){
return fa[x]!=x?fa[x]=find(fa[x]):fa[x];
}
void merge(int a,int b){
if(find(a)!=find(b)){
fa[find(a)]=find(b);
}
}
int main(){
scanf("%d",&t);
while(t--){
scanf("%d%d",&n,&m);
init();
for(int i=1;i<n;i++){
w[i].resize(m+1);
for(int j=1;j<=m;j++){
scanf("%d",&w[i][j]);
}
}
for(int i=1;i<=n;i++){
v[i].resize(m);
for(int j=1;j<m;j++){
scanf("%d",&v[i][j]);
}
}
for(int i=1;i<n;i++){
for(int j=1;j<m;j++){
s[idx(i,j)]=1ll*w[i][j]-1ll*w[i][j+1]+1ll*v[i][j]-1ll*v[i+1][j];
}
}
for(int i=1;i<n;i++){
scanf("\n");
for(int j=1;j<=m;j++){
char p;
scanf("%c",&p);
if(p=='0'){
merge(idx(i,j-1),idx(i,j));
}
}
}
for(int i=1;i<=n;i++){
scanf("\n");
for(int j=1;j<m;j++){
char q;
scanf("%c",&q);
if(q=='0'){
merge(idx(i-1,j),idx(i,j));
}
}
}
for(int i=1;i<=(n-1)*(m-1);i++){
if(find(i)!=i&&find(i)!=find(0)){
s[find(i)]+=s[i];
}
}
for(int i=1;i<=(n-1)*(m-1);i++){
if(find(i)==i&&find(i)!=find(0)){
ans+=max(s[i],0ll);
}
}
printf("%lld\n",ans);
}
return 0;
}

