int main(){

int t;
cin >> t;

while(t--){
int n;
cin >> n;

vector<int> a(n);
for(int i = 0; i < n; i++) cin >> a[i];

int ans = 0;
for(int i = 0; i < n - 1; i++) if(a[i] % (a[i] - a[i + 1]) == 0) ans++;

cout << ans << '\n';
}

return 0;
}

