ios_base::sync_with_stdio(false);
cin.tie(nullptr);

int t;
cin >> t;
while(t--) {
cin >> n;
for(int i = 1; i <= n; i++) adj[i].clear();

for(int i = 0; i < n - 1; ++i) {
int u, v;
cin >> u >> v;
adj[u].push_back(v);
adj[v].push_back(u);
}

dfs(1, 0);

int ans = 0;
for(int u = 2; u <= n; u++) {
if(cnt[u] & 1) ans++;
}

if(!(cnt[1] & 1)) cout << ans << endl;
else cout << ans - mx[1] << endl;
}

return 0;
}

