vecin(aa, n); sort(all(aa));
n --;
ll extra = aa.back(); aa.pop_back();

ll L = 0, R = extra * (ll)n;
while (L != R) {
ll mid = (L + R + 1) / 2;
vector<pair<int, ll>> dp(1 << n, {0, 0});
for (int i = 1; i < (1 << n); i ++) {
for (int j = 0; (1 << j) <= i; j ++) {
