cur.second += aa[j];
if (cur.second >= mid)
cur = {cur.first + 1, 0};
dp[i] = max(dp[i], cur);
}
}
if (dp[(1 << n) - 1].first >= k)
L = mid;
else
R = mid - 1;
}
