#define INT(...) int __VA_ARGS__; read(__VA_ARGS__)
#define LL(...) ll __VA_ARGS__; read(__VA_ARGS__)
#define VEC(type, name, size) vector<type> name(size); read(name)

void solve() {
INT(N); LL(tot); INT(X);
X--;
VEC(ll, A, N);
VEC(ll, D, N-1);
vl T(N);
T[X] = 1;
FOR(i, X, N-1) {
T[i+1] = max(T[i]+1, D[i]);
if (i == X && D[i] == 1) T[i+1] = 1;
}
FOR_R(i, X) {
T[i] = max(T[i+1]+1, D[i]);
if (i == X-1 && D[i] == 1) T[i] = 1;
}
vi nh(N), lh(N);
vc<pl> stk;
stk.eb(mp(N, 2e9));
FOR_R(i, N) {
while (stk.back().se <= A[i]) stk.pop_back();
nh[i] = stk.back().fi;
stk.eb(mp(i, A[i]));
}
stk.clear();
stk.eb(mp(-1, 2e9));
FOR(i, N) {
while (stk.back().se <= A[i]) stk.pop_back();
lh[i] = stk.back().fi;
stk.eb(mp(i, A[i]));
}

ll dp[N];
FOR(i, N) {
dp[i] = -infty<ll>;
}
FOR(i, N) dp[i] = 0;
vc<pl> vals; FOR(i, N) vals.eb(mp(T[i], i));
sort(all(vals));
ll ans = 0;
vl ps; ps.eb(0);
FOR(i, N) ps.eb(ps.back()+A[i]);
trav(xx, vals) {
int i = xx.se;
if (dp[i] < 0) continue;
chmax(ans, (tot - T[i] + 1) * A[i] + dp[i]);
vi ops = {nh[i], lh[i]};
trav(j, ops) {
if (j < 0 || j >= N) continue;
if (abs(j-i) > T[j] - T[i]) {
continue;
}
chmax(dp[j], dp[i] + (T[j] - T[i] - abs(j-i) + 1) * A[i] + ps[max(i, j)] - ps[min(i, j) + 1]);
}
}

print(ans);
}

