{
if(k <= 0) return;
int u = 6 - s - t;

if(a[k - 1] == 0)
{
moveall(k - 1, s, u);
op.pb({k, s, t});
moveall(k - 1, u, t);
}
else
{
moveall(k - 1 - a[k - 1], s, u);
op.pb({k, s, t});
moveall(k - 1 - a[k - 1], u, s);
moveall(k - 1, s, t);
}
