if(szr<pr) R=r/k-1;
else R=r/k;
solve(L,R,1);
}
}
for(int i=0;i<n;i++){
s[i]=c[i];
}
for(int i=0;i<min(n-1,k);i++){
// Handle the two partial boundary blocks separately.
pl=i+1,pr=n-1-i;
if(pr>k) continue;
if(szl<pl) L=l/k+1;
else L=l/k;
if(szr<pr) R=r/k-1;
else R=r/k;
c[0]=c[1]=s[i+1];
solve(L,R,2);
}
}
}
